import _jsPanel from 'jspanel4';
export { default } from 'jspanel4';

declare global {
    /** 
     * This namespace is used to encapsulate all provided Utils libraries.
     */
    namespace SigUtils {
        /**
         * A dependency free javascript tool to create highly configurable multifunctional floating panels.
         * Currently there are no type defintions available, therefore it is mocked using type: any.
         */
        export import JsPanel = _jsPanel
    }
    interface Window {
        /**
         * A dependency free javascript tool to create highly configurable multifunctional floating panels.
         * Currently there are no type defintions available, therefore it is mocked using type: any.
         */
        jsPanel: typeof _jsPanel
    }
}
